from math import gcd
from typing import Callable, Optional, List, Tuple

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def rank(u: Callable[[int], int], p: int, search: int = 5000) -> Optional[int]:
    for k in range(1, search + 1):
        if u(k) % p == 0:
            return k
    return None

def comparison_table(primes: List[int]) -> List[Tuple[int, Optional[int], Optional[int]]]:
    mers = lambda n: 2 ** n - 1
    rows = []
    for p in primes:
        rows.append((p, rank(fib, p), rank(mers, p)))
    return rows

if __name__ == '__main__':
    print(f"{'p':>4} | {'rank in F_n':>11} | {'rank in 2^n-1':>13}")
    print('-' * 34)
    for p, rf, rm in comparison_table([3, 7, 11, 13, 17, 23, 31]):
        print(f'{p:>4} | {str(rf):>11} | {str(rm):>13}')

