function RANK(u, p, search):
    for k = 1 to search:
        if u(k) mod p == 0:
            return k          # least positive apparition index
    return NONE               # p does not appear in window

function DIVIDES_TERM(u, p, m, rank=NONE):
    if rank == NONE:
        rank = RANK(u, p)
        if rank == NONE: return FALSE
    return (m mod rank == 0)

function JOINT_MODULUS(u, primes):
    ranks = []
    for p in primes:
        r = RANK(u, p)
        if r == NONE: return NONE
        ranks.append(r)
    L = 1
    for r in ranks:
        L = L * r / gcd(L, r)   # running lcm
    return L

